import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

const read = path => readFileSync(new URL(`../${path}`, import.meta.url), "utf8").replace(/\r\n/g, "\n");

// Shapes generated by microsoft/aspire's aspire-starter template. Service defaults are a
// solution-named shared project, not an Aspire.ServiceDefaults package.
const solution = {
  "Shop.ServiceDefaults/Shop.ServiceDefaults.csproj": `<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>net10.0</TargetFramework>
    <IsAspireSharedProject>true</IsAspireSharedProject>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="Microsoft.Extensions.ServiceDiscovery" Version="10.0.0" />
  </ItemGroup>
</Project>`,
  "Shop.ApiService/Shop.ApiService.csproj": `<Project Sdk="Microsoft.NET.Sdk.Web">
  <ItemGroup>
    <ProjectReference Include="..\\Shop.ServiceDefaults\\Shop.ServiceDefaults.csproj" />
  </ItemGroup>
</Project>`,
  "Shop.Web/Shop.Web.csproj": `<Project Sdk="Microsoft.NET.Sdk.Web">
  <ItemGroup>
    <ProjectReference Include="../Shop.ServiceDefaults/Shop.ServiceDefaults.csproj" />
  </ItemGroup>
</Project>`,
  "Shop.Tests/Shop.Tests.csproj": `<Project Sdk="Microsoft.NET.Sdk">
  <ItemGroup>
    <PackageReference Include="xunit" Version="2.9.3" />
  </ItemGroup>
</Project>`
};

function documentedMatches(markdown) {
  const section = /^### 6\. Service Defaults[^\n]*\n([\s\S]*?)(?=^---$|^## )/m.exec(markdown)?.[1];
  assert.ok(section, "Missing service defaults detection section");
  const commands = [...section.matchAll(/^grep -rl(E?) (["'])(.+?)\2 --include=["']\*\.csproj["'] \.$/gm)];
  assert.ok(commands.length > 0, "Missing service defaults grep command");
  const matched = new Set();
  for (const [, , , pattern] of commands) {
    const regex = new RegExp(pattern);
    for (const [path, contents] of Object.entries(solution)) {
      if (contents.split("\n").some(line => regex.test(line))) matched.add(path);
    }
  }
  return [...matched].sort();
}

test("service defaults detection finds template-generated shared and service projects", () => {
  const detection = read("skills/aspire-orchestration/references/detection.md");
  assert.deepEqual(documentedMatches(detection), [
    "Shop.ApiService/Shop.ApiService.csproj",
    "Shop.ServiceDefaults/Shop.ServiceDefaults.csproj",
    "Shop.Web/Shop.Web.csproj"
  ]);
});

test("routing tables do not name a nonexistent Aspire.ServiceDefaults package as the signal", () => {
  for (const path of [
    "skills/aspire/SKILL.md",
    "skills/aspire-orchestration/SKILL.md",
    "skills/aspire-orchestration/references/detection.md"
  ]) {
    const rows = read(path).split("\n").filter(line => /^\|.*(?:Service [Dd]efaults|ServiceDefaults|IsAspireSharedProject)/.test(line));
    assert.ok(rows.length > 0, `${path}: missing service defaults signal row`);
    for (const row of rows) assert.doesNotMatch(row, /Aspire\.ServiceDefaults/, `${path}: ${row}`);
  }
});
